 32	/**
 33	 * Helper: builds a minimal RootIndex and calls computeHealedStatus.
 34	 * Derives totalWps and pendingWps from wpStatuses automatically.
 35	 */
 36	function healStatus(
 37	  currentStatus: ProjectStatus,
 38	  wpStatuses: WpStatus[],
 39	  synthesisGenerated?: boolean,
 40	): ProjectStatus {
 41	  const rootIndex = {
 42	    plan_file: 'plan.md',
 43	    date_created: now(),
 44	    last_updated: now(),
 45	    status: currentStatus,
 46	    total_work_packages: wpStatuses.length,
 47	    pending_work_packages: wpStatuses.filter(
 48	      (s) => s !== 'COMPLETE' && s !== 'CANCELLED'
 49	    ).length,
 50	    work_packages: wpStatuses.map((s, i) => ({
 51	      work_package_id: `WP-${String(i + 1).padStart(3, '0')}`,
 52	      file: `work/WP-${String(i + 1).padStart(3, '0')}.md`,
 53	      status: s,
 54	      assigned_to: 'Developer' as const,
 55	      dependencies: [],
 56	    })),
 57	    project_comments: [],
 58	    ...(synthesisGenerated !== undefined ? { synthesis_generated: synthesisGenerated } : {}),
 59	  };
 60	  return computeHealedStatus(rootIndex as any).healedStatus as ProjectStatus;
 61	}
